47	        List<Map<String, Object>> clients =
48	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
49	        for (Map<String, Object> client : clients) {
50	            jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
51	                    ((Number) client.get("id")).longValue(), client.get("name"), client.get("email"));
